    {
      "tipo": "DrawCalls",
      "causa_raiz": "O número de Draw Calls atingiu um pico astronômico de 36.589 chamadas por frame (o limite orçado era 2.579), resultando em um tempo de GPU crítico de 62.48ms (mais de 3.7x acima do teto de 16.7ms para 60 FPS). Esse excesso ocorre geralmente por objetos repetidos desenhados individualmente sem GPU Instancing, ausência de Static Batching, ou excesso de materiais distintos sem Texture Atlasing.",
      "codigo_refatorado": "using UnityEngine;

public class InstanceBatcher : MonoBehaviour
{
    [SerializeField] private Mesh targetMesh;
    [SerializeField] private Material targetMaterial;
    [SerializeField] private Transform[] sourceObjects;

    private Matrix4x4[][] batches;
    private MaterialPropertyBlock propBlock;
    private const int BATCH_SIZE = 1023;

    private void Awake()
    {
        if (targetMaterial != null)
        {
            targetMaterial.enableInstancing = true;
        }
        propBlock = new MaterialPropertyBlock();
        PrepareBatches();
    }

    public void PrepareBatches()
    {
        if (sourceObjects == null || sourceObjects.Length == 0) return;
        int totalCount = sourceObjects.Length;
        int batchCount = Mathf.CeilToInt((float)totalCount / BATCH_SIZE);
        batches = new Matrix4x4[batchCount][];

        for (int b = 0; b < batchCount; b++)
        {
            int currentSize = Mathf.Min(BATCH_SIZE, totalCount - (b * BATCH_SIZE));
            batches[b] = new Matrix4x4[currentSize];
            for (int i = 0; i < currentSize; i++)
            {
                int index = (b * BATCH_SIZE) + i;
                batches[b][i] = sourceObjects[index].localToWorldMatrix;
                sourceObjects[index].gameObject.SetActive(false);
            }
        }
    }

    private void Update()
    {
        if (targetMesh == null || targetMaterial == null || batches == null) return;
        RenderParams rp = new RenderParams(targetMaterial) { matProps = propBlock };
        for (int b = 0; b < batches.Length; b++)
        {
            Graphics.RenderMeshInstanced(rp, targetMesh, 0, batches[b]);
        }
    }
}",
      "explicacao_didatica": "Cada objeto desenhado na tela exige um comando enviado pela CPU para a GPU, chamado Draw Call. Quando temos 36.589 objetos desenhados individualmente, a GPU e a fila de renderização ficam sobrecarregadas de tráfego, fazendo o jogo rodar a menos de 16 FPS. Ao ativar o GPU Instancing ou agrupar os objetos (Batching), dizemos à GPU: 'desenhe este mesmo modelo milhares de vezes em posições diferentes com apenas um comando', reduzindo dezenas de milhares de chamadas para poucas dúzias sem perder qualidade visual."
    }
  ],
  "dicas_level_design": "1. Habilitar 'Batching Static' e 'Contribute to GI' em todos os cenários estáticos (prédios, pedras, terrenos).
2. Adotar Texture Atlasing para combinar texturas de múltiplos objetos em um único material, permitindo que a Unity mescle as chamadas de desenho.
3. Configurar LODs (Level of Detail) agressivos e distâncias de culling na câmera principal (Camera Layer Cull Distances) para ocultar vegetação e pequenos adereços fora do campo de foco.
4. Fazer Occlusion Culling com 'Bake' bem ajustado no mapa para evitar a renderização de salas ou relevos ocultos por paredes ou colinas."
}

